settings.custom_liquid:
{%- assign rrp = product.metafields.custom.rrp_per_ball.value -%}
{%- assign balls = product.metafields.custom.balls_per_pack.value | default: 1 -%}
{%- if rrp -%}
  {%- assign v = product.selected_or_first_available_variant -%}
  {%- assign trade_ball = v.price | divided_by: 100.0 | divided_by: balls -%}
  {%- assign rrp_ex = rrp | divided_by: 1.2 -%}
  {%- assign margin = rrp_ex | minus: trade_ball | divided_by: rrp_ex | times: 100 | round -%}
  <p style="margin:.4rem 0 0;font-size:1.5rem">
    RRP {{ rrp | times: 100 | round | money }} per ball
    · <strong>Your margin {{ margin }}%</strong>
  </p>
{%- endif -%}

{%- assign rrp = product.metafields.custom.rrp_per_ball.value -%}
{%- assign balls = product.metafields.custom.balls_per_pack.value | default: 1 -%}
{%- if rrp -%}
  {%- assign v = product.selected_or_first_available_variant -%}
  {%- assign trade_ball = v.price | divided_by: 100.0 | divided_by: balls -%}
  {%- assign rrp_ex = rrp | divided_by: 1.2 -%}
  {%- assign margin = rrp_ex | minus: trade_ball | divided_by: rrp_ex | times: 100 | round -%}
  <div class="page-width">
    <div style="max-width:96rem;margin:0 auto;display:flex;flex-wrap:wrap;gap:.8rem 2.4rem;align-items:center;justify-content:space-between;padding:1.4rem 2rem;border:1px solid rgba(0,0,0,.12);border-radius:1.2rem;font-size:1.5rem">
      <span>RRP <strong>{{ rrp | times: 100 | round | money }}</strong> per ball · {{ balls }} balls per pack</span>
      <span>Your price <strong>{{ trade_ball | times: 100 | round | money }}</strong> per ball</span>
      <span style="background:#0097B2;color:#fff;border-radius:2rem;padding:.4rem 1.4rem;font-weight:700">Your margin {{ margin }}%</span>
    </div>
  </div>
{%- endif -%}
